const { createClient } = require('@supabase/supabase-js');

const supabase = createClient(
  process.env.NEXT_PUBLIC_SUPABASE_URL,
  process.env.SUPABASE_SERVICE_ROLE_KEY
);

async function testVenueSystem() {
  console.log('Testing venue API system...');

  try {
    // Test 1: Try to insert a test venue directly
    console.log('Testing venue insertion...');
    const testVenue = {
      place_id: 'test_place_123',
      name: 'Test Venue',
      address: '123 Test St',
      category: 'indoor',
      rating: 4.5,
      reviews_count: 100,
      latitude: 42.3314,
      longitude: -83.0458,
      zip_code: '48226'
    };

    const { data: insertData, error: insertError } = await supabase
      .from('venues')
      .insert(testVenue)
      .select()
      .single();

    if (insertError) {
      console.log('Insert error (table may not exist):', insertError.message);

      // If table doesn't exist, let's create it using manual insert
      console.log('Attempting to create venues table via manual SQL...');
      const createVenuesSQL = `
        CREATE TABLE IF NOT EXISTS venues (
          id UUID DEFAULT gen_random_uuid() PRIMARY KEY,
          place_id TEXT UNIQUE NOT NULL,
          name TEXT NOT NULL,
          address TEXT NOT NULL,
          category TEXT NOT NULL,
          rating DECIMAL(2,1),
          reviews_count INTEGER DEFAULT 0,
          latitude DECIMAL(10, 8),
          longitude DECIMAL(11, 8),
          zip_code TEXT,
          created_at TIMESTAMP WITH TIME ZONE DEFAULT NOW()
        );
      `;

      console.log('SQL to run manually in Supabase dashboard:');
      console.log(createVenuesSQL);

    } else {
      console.log('✓ Venue inserted successfully:', insertData);

      // Clean up test data
      await supabase.from('venues').delete().eq('place_id', 'test_place_123');
      console.log('✓ Test data cleaned up');
    }

  } catch (error) {
    console.error('Test failed:', error);
  }
}

testVenueSystem();
